mapper.select:
SELECT id, source, event_type AS eventType, video_id AS videoId, series_id AS seriesId, position_seconds AS positionSeconds, duration_seconds AS durationSeconds, cache_hit AS cacheHit, message, session_id AS sessionId, trace_id AS traceId, created_at AS createdAt FROM t_playback_log WHERE user_id = #{userId}
AND event_type = #{eventType}
ORDER BY id DESC LIMIT #{limit}
